"use strict";
"use client";
import { createContext } from '../../create-context.js';

const [CommandContextProvider, useCommandContext] = createContext({
  name: "CommandContext",
  hookName: "useCommandContext",
  providerName: "<Command.Root />"
});
const [CommandProviderContextProvider, useCommandProviderContext] = createContext({
  name: "CommandProviderContext",
  strict: false
});

export { CommandContextProvider, CommandProviderContextProvider, useCommandContext, useCommandProviderContext };
